-- Additive PostgreSQL feature migration for Fertini.
-- Text reviews are anonymous and moderated; no rating, email or phone is collected.
ALTER TABLE "reviews" ALTER COLUMN "user_id" DROP NOT NULL;
ALTER TABLE "reviews" ALTER COLUMN "rating" SET DEFAULT 0;
ALTER TABLE "reviews" ADD COLUMN IF NOT EXISTS "admin_reply" TEXT;

CREATE TABLE IF NOT EXISTS "support_threads" (
 "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "visitor_name" VARCHAR(70) NOT NULL,
 "subject" VARCHAR(120) NOT NULL,
 "token_hash" VARCHAR(64) NOT NULL UNIQUE,
 "status" VARCHAR(16) NOT NULL DEFAULT 'OPEN',
 "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "support_threads_status_updated_idx" ON "support_threads" ("status","updated_at");

CREATE TABLE IF NOT EXISTS "support_messages" (
 "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "thread_id" BIGINT NOT NULL REFERENCES "support_threads"("id") ON DELETE CASCADE,
 "role" VARCHAR(16) NOT NULL,
 "body" TEXT NOT NULL,
 "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "support_messages_thread_created_idx" ON "support_messages" ("thread_id","created_at");

CREATE TABLE IF NOT EXISTS "support_faq" (
 "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "question" TEXT NOT NULL,
 "answer" TEXT,
 "published" BOOLEAN NOT NULL DEFAULT FALSE,
 "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "support_faq_published_idx" ON "support_faq" ("published","updated_at");

CREATE TABLE IF NOT EXISTS "support_settings" (
 "id" INTEGER PRIMARY KEY DEFAULT 1 CHECK ("id" = 1),
 "welcome" TEXT NOT NULL DEFAULT 'به گالری فرتینی خوش آمدید؛ چه رایحه‌ای در ذهن دارید؟',
 "expected_response" TEXT NOT NULL DEFAULT 'مشاور فرتینی در اولین فرصت پاسخ می‌دهد.',
 "working_hours" TEXT NOT NULL DEFAULT '',
 "enabled" BOOLEAN NOT NULL DEFAULT TRUE,
 "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
